{
  "work_package_id": "WP-001",
  "work_package_file": "work/WP-001.md",
  "status": "IN_PROGRESS",
  "assigned_to": "QA",
  "dependencies": [],
  "acceptance_criteria": [
    {
      "criterion": "repo-status-cells.js exports buildRepoStatusCells, makeBranchTrigger, and updateRepoStatusCells as named ES module exports.",
      "met": true
    },
    {
      "criterion": "buildRepoStatusCells returns an object with branchCell, badgeCell, and actionsCell properties, each being an HTMLTableCellElement (<td>).",
      "met": true
    },
    {
      "criterion": "Each returned cell carries the correct CSS class: branchCell → .repo-branch-cell, badgeCell → .repo-badge-cell, actionsCell → .repo-actions-cell.",
      "met": true
    },
    {
      "criterion": "The badge wrapper <div> inside badgeCell retains the data-repo-id attribute.",
      "met": true
    },
    {
      "criterion": "makeBranchTrigger returns a <button> with class branch-switch-trigger, the correct textContent, and aria-label.",
      "met": true
    },
    {
      "criterion": "updateRepoStatusCells locates and updates branch and badge cells within a <tr> by CSS class (not by hardcoded cell index), using the same rebuild logic as the current updateStatusTable.",
      "met": true
    },
    {
      "criterion": "When isStable is false and onBranchCellClick is provided, the branch cell contains a clickable trigger button; when isStable is true, it renders plain text.",
      "met": true
    },
    {
      "criterion": "The Git GUI button calls api.workspaces.launch.githubDesktop(projectId, wid, repoId).",
      "met": true
    },
    {
      "criterion": "The Browse button is conditionally rendered when webserverUrl is truthy, opening the correct URL pattern.",
      "met": true
    },
    {
      "criterion": "No innerHTML assignments — all text set via textContent.",
      "met": true
    }
  ],
