  1	/**
  2	 * Unit tests for components/repo-status-cells.js — WP-001.
  3	 *
  4	 * Acceptance Criteria verified:
  5	 *   AC1  — repo-status-cells.js exports buildRepoStatusCells, makeBranchTrigger,
  6	 *           and updateRepoStatusCells as named ES module exports.
  7	 *   AC2  — buildRepoStatusCells returns { branchCell, badgeCell, actionsCell },
  8	 *           each being an HTMLTableCellElement (<td>).
  9	 *   AC3  — Each returned cell carries the correct CSS class.
 10	 *   AC4  — The badge wrapper <div> inside badgeCell retains data-repo-id.
 11	 *   AC5  — makeBranchTrigger returns a <button class="branch-switch-trigger">
 12	 *           with the correct textContent and aria-label.
 13	 *   AC6  — updateRepoStatusCells locates branch and badge cells by CSS class,
 14	 *           not by hardcoded cell index.
 15	 *   AC7  — When isStable is false and onBranchCellClick is provided, the branch
 16	 *           cell contains a clickable trigger button; when isStable is true it
 17	 *           renders plain text.
 18	 *   AC8  — The "Git GUI" button calls api.workspaces.launch.githubDesktop(projectId, wid, repoId).
 19	 *   AC9  — The "Browse" button is only rendered when webserverUrl is truthy,
 20	 *           and opens the correct URL.
 21	 *   AC10 — No innerHTML assignments — all text set via textContent.
 22	 *
 23	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 24	 * Run individually with:
 25	 *   node --test gui/public/js/components/repo-status-cells.test.mjs
 26	 */
 27	
 28	import { test, beforeEach } from 'node:test';
 29	import assert from 'node:assert/strict';
 30	import { JSDOM } from 'jsdom';
 31	
 32	// ---------------------------------------------------------------------------
 33	// jsdom setup — install globals before any module is imported
 34	// ---------------------------------------------------------------------------
 35	
 36	const dom = new JSDOM('<!DOCTYPE html><html><body><div id="toast-container"></div></body></html>', {
 37	    url: 'http://localhost/',
 38	});
 39	
 40	const { window } = dom;
 41	
 42	globalThis.document    = window.document;
 43	globalThis.window      = window;
 44	globalThis.location    = window.location;
 45	globalThis.HTMLElement = window.HTMLElement;
 46	// CSS.escape shim (jsdom may not expose the CSS global)
 47	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/["\\]/g, '\\$&') };
 48	
 49	// ---------------------------------------------------------------------------
 50	// Minimal fetch mock (required by api.js)
 51	// ---------------------------------------------------------------------------
 52	
 53	globalThis.fetch = async () => ({
 54	    status: 200,
 55	    ok: true,
 56	    statusText: 'OK',
 57	    headers: { get: () => 'application/json' },
 58	    json: async () => ({}),
 59	});
 60	
 61	// ---------------------------------------------------------------------------
 62	// Import module under test and patch api
 63	// ---------------------------------------------------------------------------
 64	
 65	const { api } = await import('../api.js');
 66	
 67	/** Calls recorded by the launch.githubDesktop spy. */
 68	const ghDesktopCalls = [];
 69	let ghDesktopShouldFail  = false;
 70	let ghDesktopFailMessage = 'GitHub Desktop not found';
 71	
 72	api.workspaces.launch.githubDesktop = async (projectId, wid, repoId) => {
 73	    ghDesktopCalls.push({ projectId, wid, repoId });
 74	    if (ghDesktopShouldFail) {
 75	        throw new Error(ghDesktopFailMessage);
 76	    }
 77	    return { success: true };
 78	};
 79	
 80	/** URLs opened by window.open spy. */
 81	const openedUrls = [];
 82	globalThis.window.open = (url, target) => {
 83	    openedUrls.push({ url, target });
 84	};
 85	
 86	const {
 87	    buildRepoStatusCells,
 88	    makeBranchTrigger,
 89	    updateRepoStatusCells,
 90	} = await import('./repo-status-cells.js');
 91	
 92	// ---------------------------------------------------------------------------
 93	// Shared fixture helpers
 94	// ---------------------------------------------------------------------------
 95	
 96	const DEFAULT_OPTS = {
 97	    repoId:     'my-repo',
 98	    repoName:   'My Repo',
 99	    statusInfo: { currentBranch: 'main', localCommits: 0, unfetchedCommits: 0, modifiedFiles: 0, lastActivity: null, hasConflicts: false },
100	    projectId:  'my-project',

101	    badgeCell.appendChild(badgeWrapper);
102	
103	    // ------------------------------------------------------------------
104	    // Actions cell — "Git GUI" button (always present) + optional "Browse"
105	    // ------------------------------------------------------------------
106	    const actionsCell = document.createElement('td');
107	    actionsCell.className = 'repo-actions-cell';
108	
109	    const openBtn = document.createElement('button');
110	    openBtn.type        = 'button';
111	    openBtn.className   = 'btn btn-secondary btn-sm';
112	    openBtn.textContent = 'Git GUI';
113	    openBtn.title       = 'Open this repository in GitHub Desktop.';
114	
115	    openBtn.addEventListener('click', async () => {
116	        openBtn.disabled    = true;
117	        openBtn.textContent = 'Opening…';
118	        try {
119	            await api.workspaces.launch.githubDesktop(projectId, wid, repoId);
120	        } catch (err) {
121	            // Import showToast lazily to avoid a hard dependency cycle; callers
122	            // that need richer error UX can wrap this function.
123	            const { showToast } = await import('../components/toast.js');
124	            showToast(err.message || 'Failed to open GitHub Desktop.', 'error');
125	        } finally {
126	            openBtn.disabled    = false;
127	            openBtn.textContent = 'Git GUI';
128	        }
129	    });
130	
131	    actionsCell.appendChild(openBtn);
132	
133	    // Browse button — shown only when webserverUrl is configured.
134	    if (webserverUrl) {
135	        const browseBtn = document.createElement('button');
136	        browseBtn.type        = 'button';
137	        browseBtn.className   = 'btn btn-secondary btn-sm';
138	        browseBtn.textContent = 'Browse';
