109	/**
110	 * Build a minimal <tr> that contains the three shared cells.
111	 * An optional first column (name cell) is added when nameFirst = true, which
112	 * means the shared cells are NOT at index 0/1/2 — used to verify that
113	 * updateRepoStatusCells does not rely on hardcoded indices.
114	 */
115	function buildRow(overrides = {}, { nameFirst = false } = {}) {
116	    const tr = document.createElement('tr');
117	    tr.dataset.repoId   = overrides.repoId   ?? DEFAULT_OPTS.repoId;
118	    tr.dataset.repoName = overrides.repoName  ?? DEFAULT_OPTS.repoName;
119	
120	    if (nameFirst) {
121	        const nameCell = document.createElement('td');
122	        nameCell.className   = 'repo-name-cell';
123	        nameCell.textContent = overrides.repoName ?? DEFAULT_OPTS.repoName;
124	        tr.appendChild(nameCell);
125	    }
126	
127	    const { branchCell, badgeCell, actionsCell } = buildCells(overrides);
128	    tr.appendChild(branchCell);
129	    tr.appendChild(badgeCell);
130	    tr.appendChild(actionsCell);
131	
132	    return tr;
133	}
